import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#73836d');
scene.fog = new THREE.FogExp2('#77836d', 0.021);
const camera = new THREE.PerspectiveCamera(43, 1, 0.1, 130);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;

scene.add(new THREE.HemisphereLight('#d9e3cb', '#34382b', 2.0));
const sun = new THREE.DirectionalLight('#ffe3b4', 3.2);
sun.position.set(-7, 15, 8); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -18; sun.shadow.camera.right = 18; sun.shadow.camera.top = 18; sun.shadow.camera.bottom = -18;
sun.shadow.bias = -0.0003; scene.add(sun);
const fill = new THREE.DirectionalLight('#8ea4c3', 1.1); fill.position.set(6, 8, -9); scene.add(fill);
const world = new THREE.Group(); scene.add(world);
const mat = (color, roughness=1, metalness=0) => new THREE.MeshStandardMaterial({color, roughness, metalness});
const groundMat = mat('#60684b');
const ground = new THREE.Mesh(new THREE.PlaneGeometry(130,130), groundMat); ground.rotation.x=-Math.PI/2; ground.receiveShadow=true; world.add(ground);
const dirt = mat('#827353'), darkDirt=mat('#62583e'), grassMats=['#546342','#626b4b','#73744f','#4b5c45'].map(c=>mat(c));
function mesh(geo, material, parent=world, x=0,y=0,z=0){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
// Winding, worn path across the clearing
for(let i=0;i<32;i++){
 const z=-18+i*1.12, x=Math.sin(i*.27)*1.45;
 const p=mesh(new THREE.CircleGeometry(1.05+Math.sin(i*3)*.16,9), i%3===0?darkDirt:dirt,world,x,.012,z);p.rotation.x=-Math.PI/2;p.rotation.z=i*.32;p.scale.x=1.28;
}
// Pebbles, leaf tufts, and fallen branches
for(let i=0;i<200;i++){
 const a=i*2.399, r=4+Math.sqrt(i)*1.05, x=Math.cos(a)*r, z=Math.sin(a)*r;
 if(Math.abs(x)<2.5) continue;
 if(i%3===0){const b=mesh(new THREE.DodecahedronGeometry(.11+(i%5)*.025,0),i%2?grassMats[0]:dirt,world,x,.06,z);b.scale.set(1.3,.6,.85)}
 else {const g=new THREE.ConeGeometry(.035,.22,3),leaf=mesh(g,grassMats[i%4],world,x,.1,z);leaf.rotation.z=(i%2?-.3:.3);leaf.rotation.y=a}
}
// Fir trees, stylized silhouettes around the playable arena
function makeTree(x,z,s=1){
 const group=new THREE.Group();world.add(group);group.position.set(x,0,z);group.scale.setScalar(s);
 mesh(new THREE.CylinderGeometry(.13,.25,1.8,6),mat('#514334'),group,0,.9,0);
 for(let j=0;j<3;j++){const c=mesh(new THREE.ConeGeometry(1.05-j*.15,2.1,7),[mat('#344b3b'),mat('#40543c'),mat('#4b5d40')][j],group,0,1.65+j*.9,0);c.rotation.y=j*.35}
 return group;
}
const trees=[[-8,-7,1.4],[8,-9,1.5],[-10,1,1.1],[10,2,1.35],[-7,10,1.3],[7,11,1.5],[-13,-11,1.5],[13,-13,1.7],[-14,7,1.5],[14,8,1.5],[-4,-14,1.25],[4,-16,1.4],[-12,-3,.9],[12,-5,1.1]];
trees.forEach(t=>makeTree(...t));
// Ancient broken stones, mossy standing stones, and a quiet golden shrine
const stone=mat('#777365'), moss=mat('#5f674b');
for(const [x,z,h] of [[-5,-2,2.5],[5,-5,3],[-6,6,2.2],[6,7,2.6]]){
 let pillar=mesh(new THREE.BoxGeometry(.8,h,.7),stone,world,x,h/2,z);pillar.rotation.y=.2;
 let cap=mesh(new THREE.BoxGeometry(1.1,.24,.92),moss,world,x,h+.05,z);cap.rotation.y=.2;
}
for(let i=0;i<5;i++){const a=i/5*Math.PI*2;const rock=mesh(new THREE.DodecahedronGeometry(.42,0),stone,world,Math.cos(a)*2.1,.25,Math.sin(a)*2.1-9);rock.scale.set(1,.75,1.1)}
const shrine= new THREE.Group(); world.add(shrine); shrine.position.set(0,0,-9);
const gold=mat('#c5a45f',.55,.55), glowMat=new THREE.MeshBasicMaterial({color:'#f9cb75'});
mesh(new THREE.TorusGeometry(.78,.045,8,32),gold,shrine,0,1.5,0).rotation.x=Math.PI/2;
const rune=mesh(new THREE.OctahedronGeometry(.23),glowMat,shrine,0,1.5,0);rune.userData.glow=true;
for(let i=0;i<3;i++){let p=mesh(new THREE.CylinderGeometry(.11,.17,1.05,6),stone,shrine,Math.cos(i*2.094)*1,0.5,Math.sin(i*2.094)*1);p.rotation.z=(i-1)*.12}
// Scatter glowing points in the mist
const fireflies=[];
for(let i=0;i<38;i++){const o=mesh(new THREE.SphereGeometry(.035,6,6),new THREE.MeshBasicMaterial({color:i%3===0?'#f4cd83':'#c5d79b'}),world,(Math.random()-.5)*24,.5+Math.random()*2,(Math.random()-.5)*26);o.userData.phase=Math.random()*6.28;fireflies.push(o)}
// Hero: an ash-cloaked wayfarer and their ember-fox companion
const hero=new THREE.Group();world.add(hero);hero.position.set(0,0,5);
const cloak=mat('#37483f'), cloakLight=mat('#58624c'), skin=mat('#c49a76'), leather=mat('#513c30'), steel=mat('#aaa99a',.48,.55), ember=mat('#d57c47'), cream=mat('#e6c691');
mesh(new THREE.CylinderGeometry(.27,.4,.85,7),cloak,hero,0,.87,0);
mesh(new THREE.SphereGeometry(.25,10,8),skin,hero,0,1.5,0);
const hood=mesh(new THREE.ConeGeometry(.34,.55,7),cloakLight,hero,0,1.8,0);hood.rotation.x=.12;
mesh(new THREE.BoxGeometry(.36,.1,.13),steel,hero,.28,1.08,-.05).rotation.z=-.42;
const blade=mesh(new THREE.BoxGeometry(.07,.72,.11),steel,hero,.52,1.27,-.12);blade.rotation.z=-.25;
mesh(new THREE.BoxGeometry(.14,.14,.15),gold,hero,.48,.86,-.1);
const cape=mesh(new THREE.ConeGeometry(.43,.88,7),mat('#713f31'),hero,-.05,.72,.3);cape.rotation.x=Math.PI;
const legs=[];for(let s of [-1,1]){const l=mesh(new THREE.CylinderGeometry(.085,.11,.45,6),leather,hero,s*.13,.26,0);legs.push(l)}
const fox=new THREE.Group();world.add(fox);fox.position.set(-.7,0,5.25);
const fur=mat('#d7864d'), furDark=mat('#9e5537'), belly=mat('#f2d3a2'), eye=mat('#28201b',.25), fxGlow=new THREE.MeshBasicMaterial({color:'#ffc36c'});
const foxBody=mesh(new THREE.SphereGeometry(.43,12,10),fur,fox,0,.48,0);foxBody.scale.set(1.15,.85,.86);
mesh(new THREE.SphereGeometry(.3,12,10),fur,fox,0,.75,-.28);
mesh(new THREE.SphereGeometry(.19,10,8),belly,fox,0,.68,-.46);
for(let s of [-1,1]){let ear=mesh(new THREE.ConeGeometry(.12,.42,5),furDark,fox,s*.2,1.03,-.31);ear.rotation.z=s*.28;mesh(new THREE.SphereGeometry(.055,8,8),eye,fox,s*.11,.79,-.52);let glint=mesh(new THREE.SphereGeometry(.018,6,6),fxGlow,fox,s*.12,.81,-.56)}
const tail=mesh(new THREE.ConeGeometry(.19,.85,7),fur,fox,0,.62,.48);tail.rotation.x=-1.05;tail.rotation.z=.2;
mesh(new THREE.ConeGeometry(.14,.28,7),cream,fox,0,.46,.91).rotation.x=-1.05;
for(let s of [-1,1])mesh(new THREE.SphereGeometry(.16,8,7),fxGlow,fox,s*.3,.4,.03);
const foxAura=mesh(new THREE.SphereGeometry(.77,12,8),new THREE.MeshBasicMaterial({color:'#ed9a4f',transparent:true,opacity:.08,side:THREE.BackSide}),fox,0,.58,0);foxAura.userData.glow=true;
// The Cindermaw: a tusked, coal-maned grove guardian
const boss=new THREE.Group();world.add(boss);boss.position.set(0,0,-4.4);
const hide=mat('#55463a'), hide2=mat('#765744'), mane=mat('#382c29'), horn=mat('#d5c6a4',.5), redEye=new THREE.MeshBasicMaterial({color:'#ff6540'});
const bbody=mesh(new THREE.SphereGeometry(1,14,10),hide,boss,0,1.15,0);bbody.scale.set(1.05,.78,.85);
mesh(new THREE.SphereGeometry(.59,12,10),hide2,boss,0,1.44,-.64).scale.set(1,.86,.92);
mesh(new THREE.SphereGeometry(.52,10,8),mane,boss,0,1.78,-.05).scale.set(1.2,.8,1.15);
const snout=mesh(new THREE.ConeGeometry(.32,.68,8),hide2,boss,0,1.25,-1.05);snout.rotation.x=-Math.PI/2;
for(let s of [-1,1]){let tusk=mesh(new THREE.ConeGeometry(.13,.58,6),horn,boss,s*.4,1.03,-1.03);tusk.rotation.z=s*.48;tusk.rotation.x=-.3;mesh(new THREE.SphereGeometry(.075,8,7),redEye,boss,s*.37,1.62,-1.12);let ear=mesh(new THREE.ConeGeometry(.17,.48,5),mane,boss,s*.48,2,-.37);ear.rotation.z=s*.55}
const bossLegs=[];for(let s of [-1,1])for(let f of [-1,1])bossLegs.push(mesh(new THREE.CylinderGeometry(.15,.21,.6,7),hide,boss,s*.58,.39,f*.48));
const maneSpikes=[];for(let i=0;i<8;i++){const x=(i%2?1:-1)*(.35+Math.floor(i/2)*.12);let sp=mesh(new THREE.ConeGeometry(.19,.58,5),mane,boss,x,1.7-(i%3)*.1,.55+Math.floor(i/2)*.14);sp.rotation.x=Math.PI/2;sp.rotation.z=(i%2?-.35:.35);maneSpikes.push(sp)}
// Target ring and attack effects
const targetRing=mesh(new THREE.TorusGeometry(1.18,.025,6,32),new THREE.MeshBasicMaterial({color:'#dbb978',transparent:true,opacity:.72}),world,0,.05,-4.4);targetRing.rotation.x=Math.PI/2;
const particles=[];
function burst(position,color,count=14,power=3){for(let i=0;i<count;i++){const p=mesh(new THREE.SphereGeometry(.045+Math.random()*.045,6,5),new THREE.MeshBasicMaterial({color,transparent:true}),world,position.x,position.y,position.z);const a=Math.random()*Math.PI*2,v=.5+Math.random()*power;p.userData={life:.45+Math.random()*.4,velocity:new THREE.Vector3(Math.cos(a)*v,Math.random()*v,Math.sin(a)*v),particle:true};particles.push(p)}}
const slash=new THREE.Mesh(new THREE.TorusGeometry(.64,.07,6,18,Math.PI*1.3),new THREE.MeshBasicMaterial({color:'#fff0c1',transparent:true,opacity:.9}));slash.rotation.x=Math.PI/2;slash.visible=false;world.add(slash);
const projectileMat=new THREE.MeshBasicMaterial({color:'#ffc36c'});const projectiles=[];

// Responsive third-person camera
let viewW=innerWidth, viewH=innerHeight;
function resize(){viewW=innerWidth;viewH=innerHeight;renderer.setSize(viewW,viewH,false);camera.aspect=viewW/viewH;camera.fov=viewW<700?48:43;camera.updateProjectionMatrix()}
addEventListener('resize',resize);resize();
const keys={};let started=false,ended=false,health=100,stamina=100,bossHealth=100,flasks=3,attackCooldown=0,dodgeTime=0,invulnerable=0,bossAttack=0,foxShots=0,elapsed=0,toastTimer=0,shake=0;
let moveX=0,moveZ=0,heroFacing=0,bossMode='approach',bossModeTime=0,walkPhase=0,foxFacing=0;
const ui={healthFill:document.querySelector('#health-fill'),healthText:document.querySelector('#health-text'),staminaFill:document.querySelector('#stamina-fill'),staminaText:document.querySelector('#stamina-text'),bossFill:document.querySelector('#boss-fill'),bossLabel:document.querySelector('#boss-health-label'),flasks:document.querySelector('#flask-count'),start:document.querySelector('#center-message'),end:document.querySelector('#end-screen'),quest:document.querySelector('#quest-text'),questSub:document.querySelector('#quest-sub'),lock:document.querySelector('#lock-indicator')};
function showToast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');toastTimer=2.2}
function updateHud(){ui.healthFill.style.width=`${health}%`;ui.healthText.textContent=Math.ceil(health);ui.staminaFill.style.width=`${stamina}%`;ui.staminaText.textContent=Math.ceil(stamina);ui.bossFill.style.width=`${bossHealth}%`;ui.bossLabel.textContent=`${Math.ceil(bossHealth)}%`;ui.flasks.textContent=flasks}
function begin(){if(started)return;started=true;ui.start.classList.add('hidden');showToast('Stay close. The grove has marked its prey.');}
document.querySelector('#start-button').addEventListener('click',begin);
function finish(win){ended=true;document.querySelector('#end-eyebrow').textContent=win?'OATH FULFILLED':'THE WILD CLAIMS YOU';document.querySelector('#end-title').textContent=win?'THE GROVE REMEMBERS':'ASHES TAKE ALL';document.querySelector('#end-copy').textContent=win?'The Cindermaw returns to the wild. A little light survives.':'The grove falls quiet. But old oaths do not die so easily.';ui.end.classList.remove('hidden')}
document.querySelector('#restart-button').addEventListener('click',()=>location.reload());
function setKey(e,on){const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=on;if(on&&!e.repeat){if(k==='j'||k===' ')action(k===' '? 'dodge':'attack');if(k==='f'||k==='e')heal()}}
addEventListener('keydown',e=>setKey(e,true));addEventListener('keyup',e=>setKey(e,false));
function action(type){if(!started||ended)return;if(type==='attack'&&attackCooldown<=0){attackCooldown=.56;hero.userData.attacking=.25;slash.position.set(hero.position.x+Math.sin(heroFacing)*.85,.85,hero.position.z-Math.cos(heroFacing)*.85);slash.rotation.set(Math.PI/2,0,-heroFacing);slash.visible=true;hero.userData.slash=.23;const dx=boss.position.x-hero.position.x,dz=boss.position.z-hero.position.z,dist=Math.hypot(dx,dz);const forward=(dx*Math.sin(heroFacing)+(-dz)*Math.cos(heroFacing))/Math.max(dist,.01);if(dist<3.05&&forward>-.25)damageBoss(15+Math.random()*5)}if(type==='dodge'&&stamina>=22&&dodgeTime<=0){stamina-=22;dodgeTime=.42;invulnerable=.55;hero.userData.dodge=.42;burst(new THREE.Vector3(hero.position.x,.48,hero.position.z),'#dbc58d',7,1.8)} }
function heal(){if(!started||ended||flasks<=0||health>=100)return;flasks--;health=Math.min(100,health+38);burst(new THREE.Vector3(hero.position.x,.8,hero.position.z),'#9bd69e',16,2);showToast('Crimson warmth returns.');updateHud()}
document.querySelector('#attack-btn').addEventListener('pointerdown',e=>{e.preventDefault();action('attack')});document.querySelector('#dodge-btn').addEventListener('pointerdown',e=>{e.preventDefault();action('dodge')});document.querySelector('#heal-btn').addEventListener('pointerdown',e=>{e.preventDefault();heal()});
// Touch joystick
const joystick=document.querySelector('#joystick'),knob=document.querySelector('#joy-knob');let joyPointer=null;
function joyMove(e){if(joyPointer!==e.pointerId)return;const r=joystick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=e.clientX-cx,dy=e.clientY-cy,max=43,len=Math.hypot(dx,dy);if(len>max){dx*=max/len;dy*=max/len}knob.style.transform=`translate(${dx}px,${dy}px)`;moveX=dx/max;moveZ=dy/max}
joystick.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);joyMove(e)});joystick.addEventListener('pointermove',joyMove);function joyEnd(e){if(e.pointerId===joyPointer){joyPointer=null;moveX=moveZ=0;knob.style.transform=''}}joystick.addEventListener('pointerup',joyEnd);joystick.addEventListener('pointercancel',joyEnd);
// Mouse click is a convenient desktop attack
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&started)action('attack')});
document.querySelector('#sound-toggle').addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='♫'?'♪':'♫';showToast('The grove answers in silence.')});
function damageBoss(amount){if(ended)return;bossHealth=Math.max(0,bossHealth-amount);boss.userData.hit=.18;shake=.16;burst(new THREE.Vector3(boss.position.x,1,boss.position.z-.8),'#f4a16d',12,3);updateHud();if(bossHealth===0){bossMode='dead';boss.userData.dead=1;ui.quest.textContent='The oath is fulfilled';ui.questSub.textContent='The grove grows quiet again.';ui.lock.style.opacity='.15';showToast('The Cindermaw has fallen.');setTimeout(()=>finish(true),850)}else if(bossHealth<45){ui.quest.textContent='Finish the Cindermaw';ui.questSub.textContent='It is wounded. Do not let up.';bossMode='enraged';showToast('The beast turns desperate!')}}
function damageHero(amount){if(invulnerable>0||ended)return;health=Math.max(0,health-amount);invulnerable=.9;hero.userData.hurt=.25;shake=.28;burst(new THREE.Vector3(hero.position.x,.9,hero.position.z),'#d77b5f',10,2.1);updateHud();if(health<=0){setTimeout(()=>finish(false),300)}else showToast('The blow staggers you.');}
const clock=new THREE.Clock();const v3=(x,y,z)=>new THREE.Vector3(x,y,z);
function update(dt){elapsed+=dt;attackCooldown=Math.max(0,attackCooldown-dt);dodgeTime=Math.max(0,dodgeTime-dt);invulnerable=Math.max(0,invulnerable-dt);stamina=Math.min(100,stamina+dt*13);bossAttack=Math.max(0,bossAttack-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show')}
 // keyboard + touch movement, relative to camera
 let ix=moveX,iz=moveZ;if(keys.a||keys.arrowleft)ix-=1;if(keys.d||keys.arrowright)ix+=1;if(keys.w||keys.arrowup)iz-=1;if(keys.s||keys.arrowdown)iz+=1;let il=Math.hypot(ix,iz);if(il>1){ix/=il;iz/=il}
 const cameraYaw=0;let wx=ix*Math.cos(cameraYaw)+iz*Math.sin(cameraYaw),wz=-ix*Math.sin(cameraYaw)+iz*Math.cos(cameraYaw);const moving=il>.06&&started&&!ended;const speed=dodgeTime>0?8.2:3.75;
 if(moving){hero.position.x+=wx*speed*dt;hero.position.z+=wz*speed*dt;heroFacing=Math.atan2(wx,-wz);hero.rotation.y=heroFacing;foxFacing=heroFacing;walkPhase+=dt*10;hero.position.y=Math.abs(Math.sin(walkPhase))*.045;legs[0].rotation.x=Math.sin(walkPhase)*.55;legs[1].rotation.x=-Math.sin(walkPhase)*.55;fox.position.x+=(hero.position.x-.72-fox.position.x)*Math.min(1,dt*4);fox.position.z+=(hero.position.z+.2-fox.position.z)*Math.min(1,dt*4)}else{hero.position.y*=.8;legs.forEach(l=>l.rotation.x*=.8);fox.position.x+=(hero.position.x-.72-fox.position.x)*Math.min(1,dt*2);fox.position.z+=(hero.position.z+.2-fox.position.z)*Math.min(1,dt*2)}
 hero.position.x=THREE.MathUtils.clamp(hero.position.x,-9,9);hero.position.z=THREE.MathUtils.clamp(hero.position.z,-12,13);fox.rotation.y=foxFacing;fox.position.y=Math.sin(elapsed*5)*.045;
 if(hero.userData.attacking>0){hero.userData.attacking-=dt;blade.rotation.z=-.25-Math.sin((1-hero.userData.attacking/.25)*Math.PI)*1.5} else blade.rotation.z=-.25;
 if(hero.userData.slash>0){hero.userData.slash-=dt;if(hero.userData.slash<=0)slash.visible=false;else{slash.scale.setScalar(1+(1-hero.userData.slash/.23)*.75);slash.material.opacity=hero.userData.slash/.23}}
 if(hero.userData.dodge>0){hero.userData.dodge-=dt;hero.rotation.z=Math.sin((1-hero.userData.dodge/.42)*Math.PI)*-.4}else hero.rotation.z*=.75;
 if(hero.userData.hurt>0){hero.userData.hurt-=dt;hero.children.forEach(c=>{if(c.material?.color)c.material.color.set(c.userData.baseColor||c.material.color)})}
 // Boss telegraphs a lunge; the glowing ring gives the player a readable dodge window.
 if(started&&!ended&&bossMode!=='dead'){
  const dx=hero.position.x-boss.position.x,dz=hero.position.z-boss.position.z,dist=Math.hypot(dx,dz);boss.rotation.y=Math.atan2(-dx,dz);
  bossModeTime+=dt;
  if(bossMode==='approach'){if(dist>2.65){boss.position.x+=dx/dist*1.35*dt;boss.position.z+=dz/dist*1.35*dt}else{bossMode='windup';bossModeTime=0;showToast('The Cindermaw gathers its strength…')}}
  else if(bossMode==='windup'){targetRing.material.opacity=.35+Math.sin(elapsed*18)*.4;targetRing.scale.setScalar(1+Math.sin(elapsed*18)*.08);if(bossModeTime>1.0){bossMode='lunge';bossModeTime=0;bossAttack=.5;}}
  else if(bossMode==='lunge'){if(bossModeTime<.32){boss.position.x+=dx/Math.max(dist,.1)*9*dt;boss.position.z+=dz/Math.max(dist,.1)*9*dt;}else{if(dist<2.1)damageHero(18);bossMode='recover';bossModeTime=0;targetRing.material.opacity=.72}}
  else if(bossMode==='recover'){if(bossModeTime>1.05){bossMode=bossHealth<45?'enraged':'approach';bossModeTime=0}}
  else if(bossMode==='enraged'){if(dist>2.25){boss.position.x+=dx/dist*2.15*dt;boss.position.z+=dz/dist*2.15*dt}else if(bossAttack<=0){bossAttack=1.5;if(dist<2.5)damageHero(12)}}
  boss.position.x=THREE.MathUtils.clamp(boss.position.x,-8,8);boss.position.z=THREE.MathUtils.clamp(boss.position.z,-9,6);bbody.scale.y=.78+Math.sin(elapsed*3)*.035;boss.position.y=bossMode==='lunge'&&bossModeTime<.32?.25:Math.abs(Math.sin(elapsed*2.2))*.035;
  if(boss.userData.hit>0){boss.userData.hit-=dt;boss.scale.setScalar(1+Math.sin(elapsed*38)*.06)}else boss.scale.setScalar(1);
  if(bossMode==='dead'){boss.scale.y=Math.max(.15,boss.scale.y-dt*1.3);boss.rotation.z+=dt*.15}
 }
 // Fox buddy periodically hurls a homing ember at the boss.
 if(started&&!ended&&bossHealth>0){foxShots+=dt;if(foxShots>2.15){foxShots=0;const orb=mesh(new THREE.SphereGeometry(.14,8,7),projectileMat,world,fox.position.x,fox.position.y+.72,fox.position.z-.45);orb.userData={projectile:true,life:2};projectiles.push(orb)}}
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i],d=v3(boss.position.x-p.position.x,1.25-p.position.y,boss.position.z-p.position.z),len=d.length();if(len<.72){damageBoss(4.5);burst(p.position,'#ffc56c',7,1.5);world.remove(p);projectiles.splice(i,1);continue}d.normalize();p.position.addScaledVector(d,dt*8);p.userData.life-=dt;if(p.userData.life<0){world.remove(p);projectiles.splice(i,1)}}
